const CACHE='invoice-gen-static-v3.0.0-r3';
const CORE=['/','/index.html','/styles.css','/app.js','/core.js','/manifest.webmanifest','/icon.svg'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(CORE);await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('invoice-gen-static-')&&key!==CACHE).map(key=>caches.delete(key)));await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET')return;const url=new URL(req.url);if(url.origin!==self.location.origin)return;event.respondWith((async()=>{const cached=await caches.match(req);if(cached)return cached;try{const response=await fetch(req);if(response.ok&&url.pathname!=='/sw.js'){const cache=await caches.open(CACHE);cache.put(req,response.clone());}return response;}catch(error){if(req.mode==='navigate')return (await caches.match('/index.html'))||Response.error();return cached||Response.error();}})());});
